"use strict";function updateTimer(){const e=Date.now(),t=deadline-e,n=Math.floor(t%36e5/6e4),r=Math.floor(t%6e4/1e3),d=document.querySelector("#progressBar"),i=300,o=.001*t;d.style.width=100*o/i+"%",document.getElementById("timer").innerHTML=`${n}m : ${r}s`,t<=0&&(clearInterval(intervalId),d.style.width="0%",document.getElementById("timer").innerHTML=expireText,$("#cashoutConfirmBtn").prop("disabled",!0))}const deadline=Date.now()+3e5,intervalId=setInterval(updateTimer,1e3);